package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * A new DRAFT claim, dated (when left undated) the sheet's entry date while it is set, else its today, its due-by fixed now: its date plus its person's own terms, else the terms of their grade on that date, else the sheet's,
 * moved past any holiday on the sheet now to the next day that is not one.
 * Due by a date inside a soft-closed period (its period is the one containing its due-by), it is a late entry.
 */
public class BuildClaim {
    public void build(@Val ClaimInput input, @Val Sheet sheet, @Val Person person, SettingsRepository settings,
            PeriodRepository periods, HolidayRepository holidays,
            Out<Claim> claimOut) {
        Settings terms = settings.find(sheet.id());
        LocalDate date = input.date() == null ? terms.entryDay(sheet.today()) : input.date();
        Claim claim = new Claim(null, sheet.id(), person.getId(), input.amount(), date, input.note(),
                ClaimStatus.DRAFT, null, null, null);
        claim.setCorrects(input.corrects());
        claim.setDueBy(holidays.pastHolidays(sheet.id(), date.plusDays(terms.termsFor(person, date))));
        claim.setLateEntry(periods.softClosedOn(sheet.id(), claim.getDueBy()) != null);
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.quick;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.ClosedPeriodException;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Refuses a quick-add while the due-by the claim would be fixed with (its date, the sheet's entry date
 * while it is set, else its today, plus its person's terms, moved past any holiday) is inside a closed period, before anything is written.
 */
public class CheckQuickAddPeriod {
    public void check(@Val Sheet sheet, @Val Person person, PeriodRepository periods, SettingsRepository settings,
            HolidayRepository holidays)
            throws ClosedPeriodException {
        Settings terms = settings.find(sheet.id());
        LocalDate date = terms.entryDay(sheet.today());
        Period closed = periods.closedOn(sheet.id(),
                holidays.pastHolidays(sheet.id(), date.plusDays(terms.termsFor(person, date))));
        if (closed != null) throw new ClosedPeriodException(closed.name());
    }
}

